package api

import (
  "encoding/json"
  "net/http"
)

type ValidationError struct {
  Field string
}

func (e *ValidationError) Error() string {
  return "invalid field: " + e.Field
}

func validate(r *Request) *ValidationError {
  if r.Name == "" {
    return &ValidationError{Field: "name"}
  }
  return nil
}

func checkQuota(u *User) *ValidationError {
  if u.Used > u.Limit {
    return &ValidationError{Field: "quota"}
  }
  return nil
}

func Handle(w http.ResponseWriter, r *Request) {
  var err error = validate(r)
  if err != nil {
    http.Error(w, err.Error(), http.StatusBadRequest)
    return
  }
  json.NewEncoder(w).Encode(r)
}

